-- =============================================================================
-- OPS KASINO & GAME STATS — OBNOVA ZE ZÁLOHY A OPRAVA AUTENTIZACE
-- Zdroj zálohy: /home/samot/Downloads/player_stats_rows.sql
-- Tento skript:
--  1. Obnoví všech 50 uživatelských účtů, herních statistik a kasino dat
--  2. Opraví a zachová autentizační data a auth-tokeny (včetně "updatedAt", verifierů a hashů)
--  3. Správně nastaví sloupec tokens podle skutečného zůstatku v gacha.tokens
--  4. Nastaví RPC funkce get_user_auth a save_user_auth pro bezproblémové přihlašování
--  5. Zabezpečí integritu triggerem, který neblokuje legitimní aktualizace
--
-- Spusťte v Supabase Dashboard -> SQL Editor (pod rolí postgres)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- KROK 1: Dočasné uvolnění triggerů pro plynulý import zálohy
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS trg_check_player_ownership ON public.player_stats;

-- -----------------------------------------------------------------------------
-- KROK 2: Ověření existence potřebných struktur a sloupců
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.player_stats (
    username text PRIMARY KEY,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now(),
    gd_completed_levels integer DEFAULT 0,
    gd_total_jumps integer DEFAULT 0,
    stratagem_highscore integer DEFAULT 0,
    total_play_time integer DEFAULT 0,
    stats jsonb,
    blackjack jsonb,
    slots jsonb,
    roulette jsonb,
    wheel jsonb,
    auth_token text,
    tokens numeric DEFAULT 2000
);

ALTER TABLE public.player_stats ADD COLUMN IF NOT EXISTS auth_token text;
ALTER TABLE public.player_stats ADD COLUMN IF NOT EXISTS tokens numeric DEFAULT 2000;

CREATE TABLE IF NOT EXISTS public.player_auth (
    username text PRIMARY KEY,
    auth jsonb NOT NULL,
    auth_token text,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);

-- RLS na privátní tabulce player_auth
ALTER TABLE public.player_auth ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "no_direct_access_player_auth" ON public.player_auth;

