-- -----------------------------------------------------------------------------
-- KROK 4: Nastavení sloupce tokens ze zálohy stats->'gacha'->>'tokens'
-- -----------------------------------------------------------------------------
UPDATE public.player_stats
SET tokens = CASE 
    WHEN stats ? 'gacha' AND (stats->'gacha'->>'tokens') IS NOT NULL 
    THEN (stats->'gacha'->>'tokens')::numeric 
    ELSE 2000 
END;

-- -----------------------------------------------------------------------------
-- KROK 5: Obnova a synchronizace autentizačních údajů (player_auth)
-- -----------------------------------------------------------------------------
-- Resetujeme auth_tokeny na NULL, aby po obnově proběhla čistá inicializace tokenu při přihlášení
UPDATE public.player_stats
SET auth_token = NULL;

-- Přenesení všech existujících hesel a solí do privátní tabulky player_auth
INSERT INTO public.player_auth (username, auth, auth_token, created_at, updated_at)
SELECT 
    username,
    stats->'auth',
    NULL,
    COALESCE(created_at, now()),
    COALESCE(updated_at, now())
FROM public.player_stats
WHERE stats ? 'auth' AND (stats->'auth') IS NOT NULL AND stats->'auth' <> 'null'::jsonb
ON CONFLICT (username) DO UPDATE
SET auth = EXCLUDED.auth,
    auth_token = NULL,
    updated_at = EXCLUDED.updated_at;

-- POZNÁMKA: stats->'auth' v player_stats záměrně NEMAZÁME, aby fungovala synchronizace 
-- i fallback dotazy v klientovi (ops-stats.js) a nedocházelo k chybám syncFromCloud.

-- -----------------------------------------------------------------------------
-- KROK 6: Oprava RPC funkcí pro bezchybné přihlašování a správu hesel
-- -----------------------------------------------------------------------------

-- 6.1 Bezpečné načtení parametrů pro ověření hesla (obsahuje "updatedAt" klíčové pro computeAuthBlind!)
CREATE OR REPLACE FUNCTION public.get_user_auth(p_username text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    auth_data jsonb;
    user_exists boolean;
BEGIN
    IF p_username IS NULL OR LENGTH(TRIM(p_username)) = 0 THEN
        RETURN jsonb_build_object('exists', false, 'hasPassword', false);
    END IF;

    -- Kontrola existence uživatele v databázi
    SELECT EXISTS (
        SELECT 1 FROM public.player_stats WHERE username = p_username
        UNION
        SELECT 1 FROM public.player_auth WHERE username = p_username
    ) INTO user_exists;

    IF NOT user_exists THEN
        RETURN jsonb_build_object('exists', false, 'hasPassword', false);
    END IF;

    -- Nejprve hledáme v tabulce player_auth
    SELECT auth INTO auth_data FROM public.player_auth WHERE username = p_username;

    -- Fallback do player_stats.stats->'auth'
    IF auth_data IS NULL THEN
        SELECT stats->'auth' INTO auth_data FROM public.player_stats WHERE username = p_username;
    END IF;

    -- Účet existuje, ale nemá nastavené žádné heslo
    IF auth_data IS NULL OR auth_data = 'null'::jsonb THEN
        RETURN jsonb_build_object(
            'exists', true,
            'hasPassword', false
        );
    END IF;

    -- Účet má heslo: vrátíme VŠECHNY parametry potřebné pro verifyPassword v JS
    RETURN jsonb_build_object(
        'exists', true,
        'hasPassword', (auth_data->>'verifier') IS NOT NULL OR (auth_data->>'hash') IS NOT NULL,
        'salt', auth_data->>'salt',
        'verifier', auth_data->>'verifier',
        'hash', auth_data->>'hash',
        'algo', COALESCE(auth_data->>'algo', 'sha256'),
        'iterations', COALESCE((auth_data->>'iterations')::int, 1),
        'blinded', COALESCE((auth_data->>'blinded')::boolean, false),
        'updatedAt', COALESCE((auth_data->>'updatedAt')::numeric, 0)
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_user_auth(text) TO anon, authenticated, service_role;

-- 6.2 Uložení nového hesla nebo registrace (synchronizuje player_auth i player_stats)
CREATE OR REPLACE FUNCTION public.save_user_auth(p_username text, p_auth jsonb, p_auth_token text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    IF p_username IS NULL OR LENGTH(TRIM(p_username)) = 0 THEN
        RAISE EXCEPTION 'Neplatné uživatelské jméno';
    END IF;

    -- Nastavíme session konfigurační příznak, aby trigger na player_stats věděl, že jde o autorizovaný save_user_auth
    PERFORM set_config('app.in_save_user_auth', 'true', true);

    -- Uložit do privátní player_auth
    INSERT INTO public.player_auth (username, auth, auth_token, updated_at)
    VALUES (p_username, p_auth, p_auth_token, now())
    ON CONFLICT (username) DO UPDATE
    SET auth = EXCLUDED.auth,
        auth_token = COALESCE(EXCLUDED.auth_token, player_auth.auth_token),
        updated_at = EXCLUDED.updated_at;

    -- Uložit auth_token a synchronizovat stats->'auth' v player_stats
    UPDATE public.player_stats
    SET auth_token = COALESCE(p_auth_token, player_stats.auth_token),
        stats = jsonb_set(COALESCE(stats, '{}'::jsonb), '{auth}', p_auth)
    WHERE username = p_username;

    RETURN true;
END;
$$;

GRANT EXECUTE ON FUNCTION public.save_user_auth(text, jsonb, text) TO anon, authenticated, service_role;

-- 6.3 Autoritativní směna sušenek na tokeny
CREATE OR REPLACE FUNCTION public.exchange_cookies(player_username text, cost numeric, gain numeric, player_auth_token text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    allowed_gain numeric;
    current_tokens numeric;
    current_cookies numeric;
    new_tokens numeric;
    new_cookies numeric;
    p_stats jsonb;
    stored_token text;
BEGIN
    IF cost <= 0 OR gain <= 0 THEN
        RAISE EXCEPTION 'Neplatná částka';
    END IF;

    -- Pevný kurz: max 160 tokenů na 1000 sušenek
    allowed_gain := FLOOR(cost * (160.0 / 1000.0));
    IF gain > allowed_gain THEN
        gain := allowed_gain;
    END IF;

    SELECT stats, auth_token INTO p_stats, stored_token 
    FROM public.player_stats 
    WHERE username = player_username 
    FOR UPDATE;

    IF p_stats IS NULL THEN
        RAISE EXCEPTION 'Hráč nenalezen';
    END IF;

    IF stored_token IS NOT NULL AND (player_auth_token IS NULL OR player_auth_token <> stored_token) THEN
        RAISE EXCEPTION 'Neautorizovaný přístup k účtu';
    END IF;

    current_cookies := COALESCE((p_stats->'clicker'->>'cookies')::numeric, 0);
    IF current_cookies < cost THEN
        RAISE EXCEPTION 'Nedostatek sušenek na účtu';
    END IF;

    new_cookies := GREATEST(0, current_cookies - cost);
    current_tokens := COALESCE((p_stats->'gacha'->>'tokens')::numeric, 2000);
    new_tokens := current_tokens + gain;

    p_stats := jsonb_set(p_stats, '{clicker,cookies}', to_jsonb(new_cookies));
    p_stats := jsonb_set(p_stats, '{gacha,tokens}', to_jsonb(new_tokens));

    UPDATE public.player_stats 
    SET stats = p_stats, tokens = new_tokens, updated_at = NOW() 
    WHERE username = player_username;

    RETURN jsonb_build_object('success', true, 'tokens', new_tokens, 'cookies', new_cookies);
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_cookies(text, numeric, numeric, text) TO anon, authenticated, service_role;

-- 6.4 Serverové roztočení rulety
CREATE OR REPLACE FUNCTION public.spin_roulette(player_username text, bet numeric, kind text, choice text, player_auth_token text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    n int;
    mult numeric := 0;
    won boolean := false;
    returned numeric := 0;
    p_stats jsonb;
    cur_tokens numeric;
    new_tokens numeric;
    stored_token text;
    is_red boolean;
    red_set int[] := ARRAY[1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
BEGIN
    IF bet <= 0 THEN
        RAISE EXCEPTION 'Neplatná výše sázky';
    END IF;

    SELECT stats, auth_token INTO p_stats, stored_token 
    FROM public.player_stats 
    WHERE username = player_username 
    FOR UPDATE;

    IF p_stats IS NULL THEN
        RAISE EXCEPTION 'Hráč nenalezen';
    END IF;

    IF stored_token IS NOT NULL AND (player_auth_token IS NULL OR player_auth_token <> stored_token) THEN
        RAISE EXCEPTION 'Neautorizovaný přístup k účtu';
    END IF;

    cur_tokens := COALESCE((p_stats->'gacha'->>'tokens')::numeric, 2000);
    IF cur_tokens < bet THEN
        RAISE EXCEPTION 'Nedostatek tokenů na účtu';
    END IF;

    n := FLOOR(random() * 37)::int;
    is_red := (n = ANY(red_set));

    IF kind = 'number' THEN
        mult := 36;
        won := (n = choice::int);
    ELSIF kind = 'color' THEN
        mult := 2;
        won := (n <> 0 AND ((choice = 'red' AND is_red) OR (choice = 'black' AND NOT is_red)));
    ELSIF kind = 'parity' THEN
        mult := 2;
        won := (n <> 0 AND ((choice = 'even' AND n % 2 = 0) OR (choice = 'odd' AND n % 2 = 1)));
    ELSIF kind = 'half' THEN
        mult := 2;
        won := (n <> 0 AND ((choice = 'low' AND n BETWEEN 1 AND 18) OR (choice = 'high' AND n BETWEEN 19 AND 36)));
    ELSIF kind = 'dozen' THEN
        mult := 3;
        won := (n <> 0 AND (
            (choice = '1' AND n BETWEEN 1 AND 12) OR
            (choice = '2' AND n BETWEEN 13 AND 24) OR
            (choice = '3' AND n BETWEEN 25 AND 36)
        ));
    END IF;

    IF won THEN
        returned := bet * mult;
        new_tokens := cur_tokens - bet + returned;
    ELSE
        returned := 0;
        new_tokens := GREATEST(0, cur_tokens - bet);
    END IF;

    p_stats := jsonb_set(p_stats, '{gacha,tokens}', to_jsonb(new_tokens));

    UPDATE public.player_stats 
    SET stats = p_stats, tokens = new_tokens, updated_at = NOW() 
    WHERE username = player_username;

    RETURN jsonb_build_object(
        'result', n,
        'won', won,
        'returned', returned,
        'net', returned - bet,
        'balance', new_tokens
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.spin_roulette(text, numeric, text, text, text) TO anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- KROK 7: Obnova ochranného triggeru pro player_stats
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.check_player_ownership_and_invariants()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    -- Pokud aktualizace probíhá zevnitř save_user_auth, povolíme změnu auth_tokenu a hesel
    IF current_setting('app.in_save_user_auth', true) = 'true' THEN
        RETURN NEW;
    END IF;

    -- 1. Ověření vlastnictví řádku (Account Takeover ochrana)
    -- Pokud má řádek nastavený auth_token (účet je chráněn heslem), pak každá aktualizace musí poslat shodný auth_token.
    IF OLD.auth_token IS NOT NULL THEN
        IF NEW.auth_token IS NULL OR NEW.auth_token <> OLD.auth_token THEN
            RAISE EXCEPTION 'Neautorizovany pristup: ucet je chranen heslem.';
        END IF;
    END IF;

    -- Aktualizace času
    NEW.updated_at := COALESCE(NEW.updated_at, now());

    -- 2. Omezení na nezáporné hodnoty (podpora libovolně velkých čísel z her)
    IF NEW.tokens IS NOT NULL AND NEW.tokens < 0 THEN
        NEW.tokens := 0;
    END IF;

    IF NEW.stats IS NOT NULL AND NEW.stats ? 'gacha' AND (NEW.stats->'gacha'->>'tokens') IS NOT NULL THEN
        IF (NEW.stats->'gacha'->>'tokens')::numeric < 0 THEN
            NEW.stats := jsonb_set(NEW.stats, '{gacha,tokens}', '0'::jsonb);
        END IF;
    END IF;

    -- 3. Ověření invariantů kasino statistik
    -- Slots
    IF NEW.slots IS NOT NULL AND NEW.slots <> '{}'::jsonb AND NEW.slots ? 'spins' THEN
        IF COALESCE((NEW.slots->>'spins')::numeric, 0) < 0 OR
           COALESCE((NEW.slots->>'totalWagered')::numeric, 0) < 0 OR
           COALESCE((NEW.slots->>'totalWon')::numeric, 0) < 0 OR
           COALESCE((NEW.slots->>'wins')::numeric, 0) > COALESCE((NEW.slots->>'spins')::numeric, 0) OR
           COALESCE((NEW.slots->>'biggest')::numeric, 0) > COALESCE((NEW.slots->>'totalWon')::numeric, 0) THEN
            NEW.slots := OLD.slots;
        END IF;
    END IF;

    -- Roulette
    IF NEW.roulette IS NOT NULL AND NEW.roulette <> '{}'::jsonb AND NEW.roulette ? 'spins' THEN
        IF COALESCE((NEW.roulette->>'spins')::numeric, 0) < 0 OR
           COALESCE((NEW.roulette->>'totalWagered')::numeric, 0) < 0 OR
           COALESCE((NEW.roulette->>'totalWon')::numeric, 0) < 0 OR
           COALESCE((NEW.roulette->>'wins')::numeric, 0) > COALESCE((NEW.roulette->>'spins')::numeric, 0) OR
           COALESCE((NEW.roulette->>'biggest')::numeric, 0) > COALESCE((NEW.roulette->>'totalWon')::numeric, 0) THEN
            NEW.roulette := OLD.roulette;
        END IF;
    END IF;

    -- Wheel
    IF NEW.wheel IS NOT NULL AND NEW.wheel <> '{}'::jsonb AND NEW.wheel ? 'spins' THEN
        IF COALESCE((NEW.wheel->>'spins')::numeric, 0) < 0 OR
           COALESCE((NEW.wheel->>'totalWagered')::numeric, 0) < 0 OR
           COALESCE((NEW.wheel->>'totalWon')::numeric, 0) < 0 OR
           COALESCE((NEW.wheel->>'wins')::numeric, 0) > COALESCE((NEW.wheel->>'spins')::numeric, 0) OR
           COALESCE((NEW.wheel->>'biggest')::numeric, 0) > COALESCE((NEW.wheel->>'totalWon')::numeric, 0) THEN
            NEW.wheel := OLD.wheel;
        END IF;
    END IF;

    -- Blackjack
    IF NEW.blackjack IS NOT NULL AND NEW.blackjack <> '{}'::jsonb AND NEW.blackjack ? 'hands' THEN
        IF COALESCE((NEW.blackjack->>'hands')::numeric, 0) < 0 OR
           COALESCE((NEW.blackjack->>'wins')::numeric, 0) > COALESCE((NEW.blackjack->>'hands')::numeric, 0) OR
           COALESCE((NEW.blackjack->>'losses')::numeric, 0) > COALESCE((NEW.blackjack->>'hands')::numeric, 0) OR
           COALESCE((NEW.blackjack->>'pushes')::numeric, 0) > COALESCE((NEW.blackjack->>'hands')::numeric, 0) OR
           COALESCE((NEW.blackjack->>'blackjacks')::numeric, 0) > COALESCE((NEW.blackjack->>'wins')::numeric, 0) THEN
            NEW.blackjack := OLD.blackjack;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_check_player_ownership ON public.player_stats;
CREATE TRIGGER trg_check_player_ownership
BEFORE UPDATE ON public.player_stats
FOR EACH ROW
EXECUTE FUNCTION public.check_player_ownership_and_invariants();

-- -----------------------------------------------------------------------------
-- KROK 8: Pohled na veřejný žebříček a oprávnění
-- -----------------------------------------------------------------------------
DROP VIEW IF EXISTS public.public_leaderboard CASCADE;

CREATE OR REPLACE VIEW public.public_leaderboard AS
SELECT 
    username,
    stratagem_highscore,
    gd_completed_levels,
    gd_total_jumps,
    total_play_time,
    tokens,
    updated_at,
    created_at,
    jsonb_strip_nulls(
        jsonb_build_object(
            'clicker', stats->'clicker',
            'gacha', stats->'gacha',
            'meta', stats->'meta',
            'gd', stats->'gd',
            'stratagem', stats->'stratagem',
            'maturita', stats->'maturita',
            'runner404', stats->'runner404',
            'hyperdrive', stats->'hyperdrive',
            'mc', stats->'mc'
        )
    ) AS stats,
    blackjack,
    slots,
    roulette,
    wheel
FROM public.player_stats;

GRANT SELECT ON public.public_leaderboard TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.player_stats TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.player_auth TO service_role;

